  ["Language for all game text, including dialogue, items and menus. Applied on the next launch."]=new[]{"Language for all game text, including dialogue, items and menus. Applied on the next launch.","Idioma de todos los textos del juego, incluidos diálogos, objetos y menús. Se aplica al iniciar el juego.","Язык всех текстов игры, включая диалоги, предметы и меню. Применяется при следующем запуске.","会話、アイテム、メニューを含むゲーム全体のテキスト言語。次回起動時に適用。","Langue de tous les textes du jeu, y compris dialogues, objets et menus. Au prochain lancement.","Sprache aller Spieltexte einschließlich Dialogen, Gegenständen und Menüs. Beim nächsten Start.","Lingua di tutti i testi del gioco, inclusi dialoghi, oggetti e menu. Al prossimo avvio.","Idioma de todos os textos do jogo, incluindo diálogos, itens e menus. No próximo início."},
  ["Spoken dialogue language. Requires the selected voice files in your game copy. Applied on the next launch."]=new[]{"Spoken dialogue language. Requires the selected voice files in your game copy. Applied on the next launch.","Idioma de los diálogos hablados. Requiere los archivos de voz correspondientes en tu copia del juego. Se aplica al iniciar el juego.","Язык озвученных диалогов. Требует соответствующих файлов озвучки в вашей копии игры. При следующем запуске.","会話の音声言語。対応する音声ファイルがゲームに必要。次回起動時に適用。","Langue des dialogues parlés. Nécessite les fichiers audio correspondants dans votre copie du jeu. Au prochain lancement.","Sprache gesprochener Dialoge. Benötigt die entsprechenden Sprachdateien in deiner Spielkopie. Beim nächsten Start.","Lingua dei dialoghi parlati. Richiede i relativi file vocali nella propria copia del gioco. Al prossimo avvio.","Idioma dos diálogos falados. Requer os arquivos de voz correspondentes na sua cópia do jogo. No próximo início."},
 };
 public static string Get(string source){
  // Launcher labels follow only the launcher's own preference, never game text or voices.
  string locale=Workspace.Current.Settings.Str("ui_language").Replace('_','-').ToLowerInvariant();
  int language=locale.Split('-')[0] switch{"es"=>1,"ru"=>2,"ja"=>3,"fr"=>4,"de"=>5,"it"=>6,"pt"=>7,_=>0};
  return Texts.TryGetValue(source,out var text)?text[language]:source;
 }
}
